        assert!(ConfigError::require_qualified("cargo/", "x").is_err());
        assert!(ConfigError::require_qualified("go/mod", "x").is_ok());
        assert!(ConfigError::require_canonical_ecosystem("go/mod", "x").is_err());
        assert!(ConfigError::require_canonical_ecosystem("pypi/pkg-*", "x").is_ok());
